import * as THREE from 'three';
export const ANIMALS=[{name:'兔',fur:0xf7f1df,inner:0xf5adb6,kind:'rabbit'},{name:'狐',fur:0xe99747,inner:0xffd1aa,kind:'fox'},{name:'貓',fur:0xe7c77d,inner:0xf5afac,kind:'cat'},{name:'熊',fur:0x96705d,inner:0xd2a78c,kind:'bear'}];
const ball=new THREE.SphereGeometry(1,16,12),cone=new THREE.ConeGeometry(1,1,4);
const material=c=>new THREE.MeshStandardMaterial({color:c,roughness:.86});
const palettes=ANIMALS.map(a=>({fur:material(a.fur),inner:material(a.inner),cream:material(0xfff5df),dark:material(0x263d36)}));
function part(g,name,geo,mat,pos,scale){let m=new THREE.Mesh(geo,mat);m.name=name;m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;g.add(m);return m;}
export function animalHead(team){let g=new THREE.Group(),a=ANIMALS[team],m=palettes[team];g.name=a.kind+'-head';part(g,'head',ball,m.fur,[0,0,0],[.76,.69,.64]);for(let x of [-.43,.43]){let rabbit=team===0,bear=team===3;let e=part(g,'ear',rabbit||bear?ball:cone,m.fur,[x,rabbit?.91:bear?.57:.68,.02],[rabbit?.21:bear?.26:.35,rabbit?.68:bear?.25:.50,rabbit?.17:.24]);e.rotation.z=-x*.25;part(e,'inner-ear',rabbit||bear?ball:cone,m.inner,[0,0,-.73],[.58,.67,.30]);}if(team===1){for(let x of [-.37,.37])part(g,'cheek',ball,m.cream,[x,-.22,-.43],[.4,.29,.25]);}part(g,'muzzle',ball,m.cream,[0,-.23,-.57],[team===3?.39:.31,.24,.23]);part(g,'nose',ball,m.dark,[0,-.12,-.79],[.105,.078,.065]);for(let x of [-.27,.27]){part(g,'eye',ball,m.dark,[x,.09,-.585],[.085,.13,.06]);part(g,'eye-glint',ball,m.cream,[x-.02,.13,-.64],[.023,.033,.012]);}if(team===2){for(let x of [-1,1])for(let yy of [-.12,-.23]){let w=part(g,'whisker',ball,m.dark,[x*.57,yy,-.58],[.22,.018,.018]);w.rotation.z=x*(yy===-.12?.15:-.15);}}return g;}
export function animalTail(team){let g=new THREE.Group(),m=palettes[team];g.name=ANIMALS[team].kind+'-tail';let t=part(g,'tail',ball,m.fur,[0,0,0],team===0?[.29,.28,.29]:team===3?[.22,.22,.23]:team===1?[.4,.36,.92]:[.17,.18,.78]);if(team===1)part(g,'white-tail-tip',ball,m.cream,[0,0,.65],[.28,.27,.36]);if(team===2)t.rotation.x=-.6;return g;}
export function pawMaterial(team){return palettes[team].fur;}
const uniforms=[0x378bdb,0xef6058,0xe7b942,0x9b6dd6].map(material);
export function animalInfantry(team){let g=new THREE.Group(),m=palettes[team],legs=[],arms=[];g.name=ANIMALS[team].kind+'-infantry';let body=part(g,'uniform',ball,uniforms[team],[0,1.25,0],[.67,.75,.48]);part(g,'belly-badge',ball,m.cream,[0,1.24,-.44],[.23,.28,.055]);let head=animalHead(team);head.position.set(0,2.15,0);g.add(head);let tail=animalTail(team);tail.position.set(0,1.05,.68);g.add(tail);for(let x of [-.32,.32]){let leg=new THREE.Group();leg.name='leg';leg.position.set(x,.72,0);part(leg,'leg-fur',ball,m.fur,[0,-.2,0],[.19,.34,.20]);part(leg,'paw',ball,m.fur,[0,-.44,-.13],[.27,.18,.37]);g.add(leg);legs.push(leg);}for(let x of [-.8,.8]){let arm=new THREE.Group();arm.name='arm';arm.position.set(x,1.6,0);part(arm,'sleeve',ball,uniforms[team],[0,-.27,0],[.23,.4,.24]);part(arm,'paw',ball,m.fur,[0,-.58,0],[.25,.22,.25]);g.add(arm);arms.push(arm);}part(g,'toy-blaster',ball,m.dark,[.78,1.2,-.55],[.19,.19,.62]);part(g,'blaster-tip',ball,m.cream,[.78,1.2,-1.05],[.22,.22,.10]);g.userData={legs,arms,species:ANIMALS[team].kind,prototype:true};return g;}
